const themeCatalog=[
 {id:'crystal',name:'Cristal da Serra',description:'Fotografia, vidro frio e foco ciano.',colors:['#142b40','#66d9ff','#c8a1ff','#e8f1f5'],accent:'#66d9ff',mode:'dark'},
 {id:'adl-night',name:'Noite Essencial',description:'Azul profundo, petróleo e assinatura em dourado fosco.',colors:['#0B1F3B','#0A4D5C','#C9A961','#B85C4E','#D4C4B0'],accent:'#C9A961',mode:'dark'},
 {id:'adl-absolute',name:'Preto Absoluto',description:'Preto real, dourado fosco e detalhes em petróleo e terracota.',colors:['#000000','#0B1F3B','#0A4D5C','#C9A961','#6B2E3E'],accent:'#C9A961',mode:'dark'},
 {id:'adl-day',name:'Luz Natural',description:'Branco quente, areia e texto em azul profundo.',colors:['#FAF8F5','#D4C4B0','#0B1F3B','#B85C4E','#0A4D5C'],accent:'#0A4D5C',mode:'light'},
 {id:'cinema',name:'Sala de Cinema',description:'Superfícies escuras, contraste alto e acentos âmbar.',colors:['#15121d','#372b3b','#e8bc82','#c7b0d6'],accent:'#e8bc82',mode:'dark'}
];
const previousThemeApply=apply;
apply=function(){previousThemeApply();const theme=themeCatalog.find(t=>t.id===prefs.theme)||themeCatalog[0];document.body.dataset.theme=theme.id;document.documentElement.style.colorScheme=theme.mode;const label=$('#themes .nav-label')||$('#themes');label.textContent='Tema';$('#themes').setAttribute('aria-label','Escolher tema. Atual: '+theme.name)};
function themePicker(){show('<p class="eyebrow">A TELA TAMBÉM É SUA</p><h2>Escolha seu tema</h2><p>Cinco atmosferas. Os controles de vidro continuam ajustáveis em todas elas.</p><div class="theme-grid">'+themeCatalog.map(t=>`<button class="theme-option" data-theme-choice="${t.id}" aria-pressed="${(prefs.theme||'crystal')===t.id}"><span class="theme-preview preview-${t.id}"><span class="preview-nav"></span><span class="preview-title"></span><span class="preview-tiles"><i></i><i></i><i></i></span><span class="preview-check">✓</span></span><strong>${t.name}</strong><small>${t.description}</small><span class="theme-swatches">${t.colors.map(c=>`<i style="background:${c}" title="${c}"></i>`).join('')}</span></button>`).join('')+'</div><p class="inline-note">Paleta dos temas Noite Essencial, Luz Natural e Preto Absoluto: azul #0B1F3B, petróleo #0A4D5C, terracota #B85C4E, dourado #C9A961, branco #FAF8F5 e areia #D4C4B0.</p><button id="theme-glass" class="panel-button">Ajustar acabamento do vidro</button>');document.querySelectorAll('[data-theme-choice]').forEach(b=>b.onclick=()=>{selectTheme(b.dataset.themeChoice);document.querySelectorAll('[data-theme-choice]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});$('#theme-glass').onclick=appearance}
function selectTheme(id){const theme=themeCatalog.find(t=>t.id===id);if(!theme)return;prefs.theme=id;prefs.accent=theme.accent;window.PeepCollections?.themeSelected(id);apply();notify('Tema aplicado: '+theme.name)}
$('#themes').onclick=themePicker;
const originalAppearance=appearance;
appearance=function(){originalAppearance();const launch=document.createElement('button');launch.className='panel-button theme-picker-launch';launch.textContent='Escolher tema';launch.onclick=themePicker;$('#panel-content').append(launch);if(prefs.theme?.startsWith('adl-')){const colors=['#0B1F3B','#0A4D5C','#B85C4E','#C9A961','#FAF8F5'];document.querySelectorAll('[data-accent]').forEach((b,i)=>{const c=colors[i];b.dataset.accent=c;b.style.background=c;b.setAttribute('aria-label','Cor de destaque '+c);b.setAttribute('aria-pressed',String(prefs.accent===c))})}};
$('#glass-shortcut').onclick=()=>appearance();apply();
